use num_bigint::BigUint;
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{fs,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/curve-model-eligibility176";
const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-08-curve-model-eligibility176";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn number(v:&Value)->BigUint{v.as_str().unwrap().parse().unwrap()}
fn review()->Value{
    let r=Path::new(R);let a=read(r.join("analysis.json"));let pins=read(r.join("pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
    assert_eq!(read(r.join("runs/result.json"))["status"],"complete");let receipt=r.join("runs/actual-field-and-small-curve-eligibility");let e=read(receipt.join("exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for(f,k)in[("stdout.log","stdout_sha256"),("stderr.log","stderr_sha256")]{assert_eq!(hash(receipt.join(f)),e[k].as_str().unwrap());}
    let p=number(&a["p"]);let one=BigUint::from(1u32);let zero=BigUint::from(0u32);assert!(p>3u32.into());assert_eq!(&p%3u32,one);assert_eq!(&p%4u32,BigUint::from(3u32));assert_eq!(a["curves"].as_array().unwrap().len(),2);
    for(i,row)in a["curves"].as_array().unwrap().iter().enumerate(){let q=number(&row["field_cardinality"]);assert_eq!(q,if i==0{p.clone()}else{&p*&p});let b=&row["B"];let chars=row["characters"].as_array().unwrap();assert_eq!(chars.len(),3);
        for(index,c)in chars.iter().enumerate(){let exponent=number(&c["exponent"]);assert_eq!(exponent*if index<2{2u32}else{3u32},&q-&one);assert_eq!(number(&c["character"][1]),zero);let result=number(&c["character"][0]);if index<2{assert_eq!(result,&p-&one);}else{assert_ne!(result,one);assert_eq!(result.modpow(&3u32.into(),&p),one);}
            for j in 0..2{let b=number(&b[j]);let expected=if index==0{b}else if index==1{(&p-((3u32*b)%&p))%&p}else{(&p-b)%&p};assert_eq!(number(&c["input"][j]),expected);}
        }
        for k in["no_rational_two_torsion","no_rational_three_torsion"]{assert_eq!(row[k],true);}for k in["same_field_montgomery_model_eligible","same_field_twisted_edwards_model_eligible","same_field_twisted_hessian_model_eligible"]{assert_eq!(row[k],false);}
    }
    assert_eq!(a["native_integer_character_agreements"],6);assert_eq!(a["toy_checks"]["prime_field_curves"],96);assert_eq!(a["toy_checks"]["extension_field_curves"],12);assert_eq!(a["toy_checks"]["finite_points_checked"],5585);assert_eq!(a["toy_checks"]["character_certificate_cases"],108);assert_eq!(a["new_proofs"],0);assert_eq!(a["new_timings"],0);assert_eq!(a["proof_ledger_count"],37023);assert_eq!(a["production_changed"],false);assert_eq!(a["goal_achieved"],false);
    json!({"source_pins_checked":pins.as_object().unwrap().len(),"receipt_and_stream_hashes_match":true,"certificate_exponents_inputs_characters_and_implications_checked":true,"same_agent_separate_reviewer":true,"native_and_toy_screen_replayed":false,"decision":"Same-field twisted Hessian, Montgomery and twisted Edwards conversions are unavailable for G1 and actual G2 twist; no native optimization selected.","new_proofs":0,"new_timings":0,"production_changed":false,"goal_achieved":false})
}
fn publish(){
    let r=Path::new(R);let d=Path::new(D);assert!(!d.exists());assert!(read(r.join("review.json"))["receipt_and_stream_hashes_match"].as_bool().unwrap());let er=r.join("review-runs/certificate-receipt-review");let e=read(er.join("exit.json"));assert_eq!(e["returncode"],0);assert_eq!(e["success"],true);for(f,k)in[("stdout.log","stdout_sha256"),("stderr.log","stderr_sha256")]{assert_eq!(hash(er.join(f)),e[k].as_str().unwrap());}for(p,h)in read(r.join("review-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
    let mut body=String::from("# Alternative curve-model eligibility on BN254\n\n**Twisted Hessian, Montgomery and twisted Edwards conversions over the current coordinate fields are unavailable for both prover groups.** Exact character certificates show that G1 over Fp and the actual G2 twist over Fp2 have no rational points of order two or three. No conversion code, native optimization, timing or proof is added; production remains unchanged. This closes this specific coordinate-model route, not all arithmetic or MSM optimizations.\n\nThis checks a change of algebraic model before investing in addition kernels. Montgomery curves contain rational2-torsion at (0,0); twisted Edwards curves contain it at (0,-1). Their equations and group laws are in the [Explicit-Formulas Database](https://www.hyperelliptic.org/EFD/g1p/auto-montgom.html), [twisted Edwards entry](https://www.hyperelliptic.org/EFD/g1p/auto-twisted.html). Section5 of [Twisted Hessian Curves](https://eprint.iacr.org/2015/781) establishes rational3-torsion for twisted Hessian curves over finite fields. Its Section5 text was available in search; the author PDF fetch timed out, so full-paper reading is not claimed. A field-defined group isomorphism preserves rational torsion. No external code or performance estimate is imported.\n\nFor y²=x³+B, finite2-torsion requires x³=-B. The certificate (-B)^((q-1)/3)≠1 rules out that root when q≡1 modulo3. Finite3-torsion satisfies ψ3=3x(x³+4B)=0. At x=0 its y-coordinate would square to B; at x³=-4B it would square to -3B. Both are quadratic nonresidues, excluding all finite3-torsion. These checks apply to the full coordinate-field curve, not just its chosen prime-order subgroup. They do not use an asserted full group order.\n\n|Actual group|Coordinate field|Quadratic character B / -3B|Cubic character of -B|Rational2-torsion|Rational3-torsion|\n|---|---|---|---|---|---|\n|G1|Fp|-1 / -1|β ≠ 1, β³=1|Absent|Absent|\n|G2 sextic twist|Fp2|-1 / -1|β ≠ 1, β³=1|Absent|Absent|\n\nHere p=21888242871839275222246405745257275088696311157297823662689037894645226208583 and β=21888242871839275220042445260109153167277707414472061641714758635765020556616. G1 uses B=3; G2 uses B=3/(9+u), u²=-1. The independent integer implementation reconstructs this twist coefficient and matches the actual production constants. It does not substitute the untwisted Fp curve into the Fp2 test. Full public inputs, exponents and residues are in the [certificates](artifacts/analysis.json).\n\nThe original native field library and a separately implemented BigUint Fp/Fp2 arithmetic agree on all six character values. Native square-root rejection supplies a secondary same-backend check. Complete point enumeration over96 prime-field curves and12 extension-field curves checks5,585 finite points: direct [2]P/[3]P group addition agrees with the torsion-polynomial criteria. All108 small-curve character cases pass, including71 certificates excluding2-torsion and53 excluding3-torsion. These toy cases test the criterion implementation; they are not an exhaustive BN254 field proof.\n\nOne new Rust1.98.1/xtask screen and one separately written certificate/receipt review pass on their first executions. All176 accepted source hashes match, with182 screen pins. The reviewer checks exponents, certificate inputs/results, implications, counts and exact receipts without rerunning the native/toy screen. It is by the same agent, not an external audit. An unused Field import warning remains; no cleanup rebuild was performed. Helper compilation/preparation/publication have tool-transcript evidence rather than complete workflow receipts.\n\nThe result concerns isomorphic models over unchanged coordinate fields. Extension fields, other curves/protocols, nonisomorphic mappings and different addition formulas are not evaluated or ruled out. There is no latency, memory-peak, minimum-RAM, concurrency, mobile, giant-circuit or AWS/Aeglos result. No key copies, lookup tables or retained solver plans are introduced.\n\n## Accepted CPU and Metal comparisons, inherited\n\nThe [latest full SDK campaign](../2026-11-08-tree-policy-sdk176/README.md) supplies these local32-worker accepted-build medians. Supplied M5 CPU/Metal references were not remeasured; ratios compare different machines. Historical same-build primary7.915095ms remains valid; latest8.040649ms does not establish an adopted regression.\n\n|Shape|Accepted CPU ms|M5 CPU ms|M5 Metal ms|CPU speedup|Metal speedup|CPU10× target ms|\n|---|---:|---:|---:|---:|---:|---:|\n");
    for(shape,t,cpu,metal)in[("1×2",8.040649245,37.,24.),("2×2",11.149096784,59.,30.),("4×2",16.069415294,109.,48.),("8×2",24.131177863,189.,74.),("12×2",33.940627784,284.,101.),("16×2",40.164083059,335.,124.),("24×2",66.187704392,528.,176.),("merge24×1",65.361571353,507.,175.)]{body.push_str(&format!("|{shape}|{t:.6}|{cpu:.0}|{metal:.0}|{:.3}×|{:.3}×|{:.1}|\n",cpu/t,metal/t,cpu/10.));}
    body.push_str("\nMerge54×1 remains160.890372ms without a supplied M5 reference. All eight CPU10× targets remain active and unmet,0/8. Accepted SDK6d83 and canonical37,023-proof ledger are unchanged.\n\n[Design](artifacts/design.md), [screen](artifacts/screen.rs), [separate review/publisher](artifacts/close.rs), [review result](artifacts/review.json), [source pins](artifacts/pins.json), workflow/command/exit/stream receipts and [checksums](SHA256SUMS) preserve the study. All numerical parameters are public curve constants; no keys, witnesses, point/scalar fixtures, proofs, executables or libraries are published.\n");
    fs::create_dir_all(d.join("artifacts")).unwrap();fs::write(d.join("README.md"),body).unwrap();let mut files=vec![PathBuf::from("README.md")];
    for file in["design.md","screen.rs","analysis.json","pins.json","plan.json","close.rs","review.json","review-plan.json","review-pins.json"]{let to=Path::new("artifacts").join(file);fs::copy(r.join(file),d.join(&to)).unwrap();assert_eq!(hash(r.join(file)),hash(d.join(&to)));files.push(to);}
    for(root,step,label)in[("runs","actual-field-and-small-curve-eligibility","screen"),("review-runs","certificate-receipt-review","review")]{for file in["command.json","exit.json","stdout.log","stderr.log"]{let from=r.join(root).join(step).join(file);let to=PathBuf::from(format!("artifacts/{label}-{file}"));fs::copy(&from,d.join(&to)).unwrap();assert_eq!(hash(from),hash(d.join(&to)));files.push(to);}for file in["result.json","protocol.json"]{let from=r.join(root).join(file);let to=PathBuf::from(format!("artifacts/{label}-{file}"));fs::copy(&from,d.join(&to)).unwrap();assert_eq!(hash(from),hash(d.join(&to)));files.push(to);}}
    files.sort();fs::write(d.join("SHA256SUMS"),files.iter().map(|p|format!("{}  {}\n",hash(d.join(p)),p.display())).collect::<String>()).unwrap();println!("Published {} source/certificate/receipt files plus checksums; no optimization or timing claim",files.len());
}
fn main(){match std::env::args().nth(1).as_deref(){Some("review")=>{let v=review();assert!(!Path::new(R).join("review.json").exists());fs::write(Path::new(R).join("review.json"),serde_json::to_vec_pretty(&v).unwrap()).unwrap();println!("Certificate implications and all receipts match; unchanged-field model route closed");},Some("publish")=>publish(),_=>panic!("review | publish")}}
